import { ScalekitClient } from '@scalekit-sdk/node';
import * as fs from 'fs';

async function main() {
  const envUrl = process.env.SCALEKIT_ENV_URL || '';
  const clientId = process.env.SCALEKIT_CLIENT_ID || '';
  const clientSecret = process.env.SCALEKIT_CLIENT_SECRET || '';

  const scalekit = new ScalekitClient(envUrl, clientId, clientSecret);

  const userId = 'zealt-user01';

  // Try to find the correct method signature if it differs
  try {
    const githubToolsResult = await scalekit.tools.listScopedTools({
      identifier: userId,
      connectionName: 'github-test',
      pageSize: 100
    });
    console.log(githubToolsResult);
  } catch(e: any) {
    console.log("Error 1:", e.message);
    try {
      const githubToolsResult = await scalekit.tools.listScopedTools(userId, 'github-test', { pageSize: 100 });
      console.log(githubToolsResult);
    } catch(e2: any) {
      console.log("Error 2:", e2.message);
    }
  }
}

main().catch(console.error);

